Rewrite the following GNU C++11 code into exactly 5 different variants. The code reads and writes I/O from the console. Each variant should have the exact same functionality as the given code, meaning that it should have the same output for any given input. Make the variants meaningfully different from one another and from the original code, while preserving functionality exactly.
Print all 5 rewritten variants, numbered from 1 to 5. Do not stop early, do not skip an index, and do not repeat an index. Use this exact format:
<perturbed_code_1>
<your_rewritten_code_1>
</perturbed_code_1>
<perturbed_code_2>
<your_rewritten_code_2>
</perturbed_code_2>
<perturbed_code_3>
<your_rewritten_code_3>
</perturbed_code_3>
<perturbed_code_4>
<your_rewritten_code_4>
</perturbed_code_4>
<perturbed_code_5>
<your_rewritten_code_5>
</perturbed_code_5>
Each block must contain one complete program. Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to rewrite:
<original_code>
#include<algorithm>
#include<iostream>
#include<cstring>
#include<cstdio>
using namespace std;
const int maxn = 8;
const int SZ = 1048576 + 5;
const int MOD = 1000000007;

inline int inc(int a, int b) { return (a + b >= MOD) ? (a + b - MOD) : (a + b); }
inline int dec(int a, int b) { return (a >= b) ? (a - b) : (a + MOD - b); }
inline int mul(int a, int b) { return 1LL * a * b % MOD; }

inline void updata(int &x, int y) { x = inc(x,y); }

inline int power(int x, int k) {
	int tmp = 1;
	while(k) {
		if(k & 1) tmp = mul(tmp,x);
		x = mul(x,x);
		k >>= 1;
	}
	return tmp;
}

int n, a[maxn][maxn], inv100, g[maxn][maxn], p[SZ], num[7][7][7], all, Ans;

inline bool check(int x, int y, int z) {
	int pos[4], lis[4];
	lis[1] = x; lis[2] = y; lis[3] = z;
	for(int i = 1;i <= 3;i ++) pos[i] = i;
	do{
		int flag = 1;
		for(int i = 1;i <= 3;i ++) {
			if(!g[pos[i]][lis[i]]) flag = 0;
		}
		if(flag) return 1;
	}while(next_permutation(pos + 1,pos + 3 + 1));
	return 0;
}

void dfs1(int now, int x, int y) {
	bool used[7];
	if(!now) return;
//	cout << now << ' ' << x << ' ' << y << endl;
	if(now == 0 && x == 4 && y == 1) {
		int xxx;
		xxx ++;
	}
  if(x == 4) {
		for(int i = 1;i <= 6;i ++) used[i] = 1;
		int sta = 0;
		if(now) {
			int xxx;
			xxx ++;
		}
		for(int i = 1;i <= 6;i ++) {
			for(int j = i + 1;j <= 6;j ++) {
				for(int k = j + 1;k <= 6;k ++) {
					if(check(i,j,k)) {
						int X, Y, Z; X = Y = Z = - 1;
						used[i] = used[j] = used[k] = 0;
						for(int l = 1;l <= 6;l ++) {
							if(!used[l]) continue;
							if(X == -1) X = l;
							else if(Y == -1) Y = l;
							else Z = l;
						}
						used[i] = used[j] = used[k] = 1;
						if(Z == -1) continue;
            sta |= num[X][Y][Z];
					}
				}
			}
		}
		updata(p[sta],now);
		return;
	}
	g[x][y] = 1; int nxt = mul(now,a[x][y]);
	if(y == 6) dfs1(nxt,x + 1,1);
	else dfs1(nxt,x,y + 1);
	g[x][y] = 0; nxt = mul(now,dec(1,a[x][y]));
	if(y == 6) dfs1(nxt,x + 1,1);
	else dfs1(nxt,x,y + 1);
}

void dfs2(int now, int x, int y) {
	if(!now) return;
	if(x == 7) {
		int sta = 0;
		for(int i = 1;i <= 6;i ++) {
			for(int j = i + 1;j <= 6;j ++) {
				for(int k = j + 1;k <= 6;k ++) {
					if(check(i,j,k)) sta |= num[i][j][k];
				}
			}
		}
		updata(Ans,mul(now,p[all ^ sta]));
		return;
	}
  g[x - 3][y] = 1; int nxt = mul(now,a[x][y]);
	if(y == 6) dfs2(nxt,x + 1,1);
	else dfs2(nxt,x,y + 1);
	g[x - 3][y] = 0; nxt = mul(now,dec(1,a[x][y]));
	if(y == 6) dfs2(nxt,x + 1,1);
	else dfs2(nxt,x,y + 1);
}

int main() {
//	freopen("data1.in","r",stdin);
  scanf("%d", &n); inv100 = power(100,MOD - 2);
	for(int i = 1;i <= n;i ++) {
		for(int j = 1;j <= n;j ++) scanf("%d", &a[i][j]), a[i][j] = mul(a[i][j],inv100);
	}
	for(int i = n + 1;i <= 6;i ++) a[i][i] = 1;
	int cnt = 0;
	for(int i = 1;i <= 6;i ++) {
		for(int j = i + 1;j <= 6;j ++) {
			for(int k = j + 1;k <= 6;k ++) {
				num[i][j][k] = 1 << cnt;
				cnt ++;
			}
		}
	}
	all = (1 << cnt) - 1;
	dfs1(1,1,1);
//	puts("");
	for(int j = 0;j < cnt;j ++) {
		for(int i = 0;i < (1 << cnt);i ++) {
			if(i & (1 << j)) updata(p[i],p[i ^ (1 << j)]);
		}
	}
//	for(int i = 0;i < (1 << cnt);i ++) if(p[i]) printf("%d %d\n", i, p[i]);
	Ans = 0;
	dfs2(1,4,1);
	Ans = dec(1,Ans);
	printf("%d\n", Ans);
	return 0;
}

